package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
final class ImportedJournalsBrowserAcceptance {
 static void click(Page p,String label){ServiceOutagesBrowserAcceptance.click(p,label);}
 static void run(BrowserTest h)throws Exception{
  String record=id(),comment=id(),note=id(),reader="JournalBrowser"+id().substring(0,8);ImportedJournalsAcceptance.seed(record,comment,note);try(var db=h.store.open()){PlatformFoundationTest.bind(db);Service.createAccount(db,map("name",reader,"password",WorkflowSupport.PASSWORD,"role","requester"));db.connection.commit();}
  try(var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext();var requesterContext=browser.newContext()){
   var page=context.newPage();h.login(page,"admin");page.navigate(h.base()+"/admin/migrations");TransferBrowserAcceptance.saved(page);page.locator("#migration-plan").fill(JSON.writeValueAsString(ImportedJournalsAcceptance.plan()));page.locator("#migration-create button").click();TransferBrowserAcceptance.saved(page);String job=page.locator("#migration-jobs").inputValue();page.locator("#migration-token").fill(MigrationSource.TOKEN);page.locator("#migration-fetch").click();assertThat(page.locator("#migration-report")).containsText("review");TransferBrowserAcceptance.saved(page);page.locator("#migration-preview").click();TransferBrowserAcceptance.saved(page);page.locator("#migration-apply").click();assertThat(page.locator("#migration-report")).containsText("\"preview\": false");page.navigate(h.base()+"/record/sc_request/"+record);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Imported journal history")).press("Enter");page.getByLabel("Migration job ID").fill(job);page.getByLabel("Source journal ID").fill(comment);click(page,"Review journal publication");assertThat(page.locator("main")).containsText("All users who can currently read");assertThat(page.locator("main")).containsText("comments preserved <script>source</script>");assertThat(page.locator("main script")).hasCount(0);ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/imported-journal-review-light.png")).setFullPage(true));page.getByLabel("Publish this exact entry to the displayed record audience").check();click(page,"Publish reviewed journal");assertThat(page.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Imported comment").setExact(true))).hasCount(1);page.navigate(page.url()+"?after=2147483647");page.getByLabel("Migration job ID").fill(job);page.getByLabel("Source journal ID").fill(note);click(page,"Review journal publication");assertThat(page.locator("main")).containsText("Staff who can currently read");page.getByLabel("Publish this exact entry to the displayed record audience").check();click(page,"Publish reviewed journal");assertThat(page.locator("main")).containsText("Imported staff work note");click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/imported-journal-staff-dark.png")).setFullPage(true));
   try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);RecordAccess.change(db,Service.record(db,"sc_request",record),actor,map("visibility","workspace","owner_id",""));db.update("INSERT INTO os_requester_record(record_id,user_id) VALUES(?,?)",record,RecordAccess.owner(db,reader));db.connection.commit();}var requester=requesterContext.newPage();FulfilmentBrowserAcceptance.login(h,requester,reader);requester.navigate(h.base()+"/record/sc_request/"+record);requester.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Imported journal history")).press("Enter");assertThat(requester.locator("main")).containsText("comments preserved <script>source</script>");assertThat(requester.locator("main")).not().containsText("work_notes preserved");assertThat(requester.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Review journal publication"))).hasCount(0);click(requester,"Dark mode");requester.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(requester);assertEquals(false,requester.evaluate("document.documentElement.scrollWidth>window.innerWidth"));requester.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/imported-journal-requester-dark.png")).setFullPage(true));String exported=requesterContext.request().get(h.base()+ImportedJournalsAcceptance.route(record)).text();assertTrue(exported.contains("comments preserved"));assertFalse(exported.contains("work_notes preserved"));try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);RecordAccess.change(db,Service.record(db,"sc_request",record),actor,map("visibility","private","owner_id",actor));db.connection.commit();}assertEquals(404,requesterContext.request().get(h.base()+ImportedJournalsAcceptance.route(record)).status());
  }finally{MigrationSource.reset();}
 }
}
